import test from "node:test";
import assert from "node:assert/strict";
import { Effect } from "effect";
import { api } from "../src/api.ts";
import { memoryStore } from "../src/memory-store.ts";
const carrier = { createLabel: () => Effect.succeed({ tracking: "t1" }) };
const order = {
  id: "o1",
  customerId: "c1",
  status: "open" as const,
  lines: [
    { sku: "a", unitCents: 1000, quantity: 2 },
    { sku: "b", unitCents: 250, quantity: 3 },
  ],
};
test("summary returns exactly the order header fields with totals", async () => {
  const service = api(memoryStore([order]), carrier);
  const summary = await Effect.runPromise(service.summary("o1"));
  assert.deepEqual(summary, {
    id: "o1",
    customerId: "c1",
    itemCount: 5,
    subtotalCents: 2750,
    status: "open",
  });
});
test("summary reports shipped status", async () => {
  const service = api(memoryStore([{ ...order, status: "shipped" }]), carrier);
  const summary = await Effect.runPromise(service.summary("o1"));
  assert.equal(summary.status, "shipped");
});
test("summary of a missing order fails with OrderNotFound", async () => {
  const service = api(memoryStore(), carrier);
  const error = await Effect.runPromise(Effect.flip(service.summary("absent")));
  assert.equal(error["_tag"], "OrderNotFound");
  assert.equal(error.orderId, "absent");
});

