import { Effect } from "effect";
import type { OrderStore } from "./order-store.ts";
import { OrderNotFound } from "./errors.ts";
export function orders(store: OrderStore) {
  const find = Effect.fn("orders.find")(function* (id: string) {
    const order = yield* store.get(id);
    if (!order) return yield* Effect.fail(new OrderNotFound(id));
    return order;
  });
  const summary = Effect.fn("orders.summary")(function* (id: string) {
    const order = yield* find(id);
    return {
      id: order.id,
      customerId: order.customerId,
      itemCount: order.lines.reduce((total, line) => total + line.quantity, 0),
      subtotalCents: order.lines.reduce((total, line) => total + line.unitCents * line.quantity, 0),
      status: order.status,
    };
  });
  return { find, summary };
}

