import test from "node:test";
import assert from "node:assert/strict";
import { Effect } from "effect";
import { orders } from "../src/orders.ts";
import { memoryStore } from "../src/memory-store.ts";
import { api } from "../src/api.ts";
test("missing orders fail at the service boundary", async () => {
  const result = await Effect.runPromise(Effect.flip(orders(memoryStore()).find("absent")));
  assert.equal(result["_tag"], "OrderNotFound");
  assert.equal(result.orderId, "absent");
});

test("api summary returns the exact order summary with quantities and subtotal", async () => {
  const order = {
    id: "order-1",
    customerId: "customer-2",
    lines: [
      { sku: "a", unitCents: 125, quantity: 2 },
      { sku: "b", unitCents: 80, quantity: 3 },
    ],
    status: "open" as const,
  };
  const result = await Effect.runPromise(api(memoryStore([order]), { ship: () => Effect.succeed({ tracking: "t" }) }).summary(order.id));
  assert.deepEqual(result, {
    id: "order-1",
    customerId: "customer-2",
    itemCount: 5,
    subtotalCents: 490,
    status: "open",
  });
});

test("api summary preserves OrderNotFound for missing orders", async () => {
  const result = await Effect.runPromise(Effect.flip(api(memoryStore(), { ship: () => Effect.succeed({ tracking: "t" }) }).summary("absent")));
  assert.equal(result["_tag"], "OrderNotFound");
  assert.equal(result.orderId, "absent");
});

