import test from "node:test";
import assert from "node:assert/strict";
import { quote } from "../src/quote.ts";
import { receipt } from "../src/receipt.ts";
const order = (unitCents: number, quantity = 1) => ({
  id: "o",
  customerId: "c1",
  status: "open" as const,
  lines: [{ sku: "a", unitCents, quantity }],
});
test("subtotal 4999 pays handling: 4999 + 400 + round(999.8) = 6399", () => {
  assert.equal(quote(order(4999)), 6399);
  assert.equal(receipt(order(4999)), "o: 6399 cents");
});
test("subtotal 5000 waives handling: 5000 + 0 + 1000 = 6000", () => {
  assert.equal(quote(order(5000)), 6000);
  assert.equal(receipt(order(5000)), "o: 6000 cents");
});
test("tax rounds to the nearest cent: 13 -> 2.6 -> 3", () => {
  assert.equal(quote(order(13)), 416);
  assert.equal(receipt(order(13)), "o: 416 cents");
});
test("tax rounds down below .5: 12 -> 2.4 -> 2", () => {
  assert.equal(quote(order(12)), 414);
  assert.equal(receipt(order(12)), "o: 414 cents");
});
test("subtotal sums line quantities before the threshold check", () => {
  assert.equal(quote(order(2500, 2)), 6000);
});

