import type { Line } from "./order.ts";
export const subtotal = (lines: ReadonlyArray<Line>): number =>
  lines.reduce((sum, line) => sum + line.unitCents * line.quantity, 0);
export const remaining = (cents: number, percent: number): number =>
  Math.round((cents * percent) / 100);
const handling = (subtotalCents: number): number => (subtotalCents >= 5000 ? 0 : 400);
const tax = (subtotalCents: number): number => Math.round(subtotalCents * 0.2);
export const orderTotal = (lines: ReadonlyArray<Line>): number => {
  const base = subtotal(lines);
  return base + handling(base) + tax(base);
};

