import type { Line, Order } from "./order.ts";
export const subtotal = (lines: ReadonlyArray<Line>): number =>
  lines.reduce((sum, line) => sum + line.unitCents * line.quantity, 0);
export const remaining = (cents: number, percent: number): number =>
  Math.round((cents * percent) / 100);

export const fulfillmentTotal = (order: Order): number => {
  const orderSubtotal = subtotal(order.lines);
  const handling = orderSubtotal < 5000 ? 400 : 0;
  const tax = Math.round(orderSubtotal * 0.2);
  return orderSubtotal + handling + tax;
};

