import test from "node:test";
import assert from "node:assert/strict";
import { quote } from "../src/quote.ts";
import { receipt } from "../src/receipt.ts";
test("small orders include handling and tax", () => {
  const order = {
    id: "o1",
    customerId: "c1",
    status: "open" as const,
    lines: [{ sku: "a", unitCents: 1000, quantity: 2 }],
  };
  assert.equal(quote(order), 2800);
  assert.equal(receipt(order), "o1: 2800 cents");
});
test("large orders waive handling", () => {
  const order = {
    id: "o2",
    customerId: "c1",
    status: "open" as const,
    lines: [{ sku: "a", unitCents: 5000, quantity: 1 }],
  };
  assert.equal(quote(order), 6000);
});

test("pricing thresholds and tax rounding are shared by quote and receipt", () => {
  const order = (id: string, unitCents: number) => ({
    id,
    customerId: "c1",
    status: "open" as const,
    lines: [{ sku: "a", unitCents, quantity: 1 }],
  });

  assert.equal(quote(order("below", 4999)), 6399);
  assert.equal(receipt(order("below", 4999)), "below: 6399 cents");
  assert.equal(quote(order("at", 5000)), 6000);
  assert.equal(receipt(order("at", 5000)), "at: 6000 cents");
  assert.equal(quote(order("rounds-up", 3)), 404);
  assert.equal(receipt(order("rounds-up", 3)), "rounds-up: 404 cents");
});

