import { Effect, Schedule } from "effect";
import type { Carrier } from "./carrier.ts";
import type { CarrierFailure } from "./errors.ts";
import type { OrderStore } from "./order-store.ts";
import { orders } from "./orders.ts";
// Three total attempts: the first call plus two retries.
const maxRetries = 2;
export const carrierBackoff = Schedule.exponential("200 millis");
export function shipping(
  store: OrderStore,
  carrier: Carrier,
  backoff: Schedule.Schedule<unknown, CarrierFailure> = carrierBackoff,
) {
  // Bound the retries here so no injected backoff can exceed the attempt limit.
  const retrySchedule = backoff.pipe(Schedule.upTo({ times: maxRetries }));
  return Effect.fn("shipping.ship")(function* (id: string) {
    const order = yield* orders(store).find(id);
    // The idempotency key is built once, so every attempt sends the same key.
    const label = yield* carrier
      .createLabel({ orderId: id, idempotencyKey: `ship:${id}` })
      .pipe(Effect.retry({ schedule: retrySchedule, while: (failure) => failure.retryable }));
    yield* store.put({ ...order, status: "shipped" });
    return label;
  });
}

