import test from "node:test";
import assert from "node:assert/strict";
import { Effect, Schedule } from "effect";
import { api } from "../src/api.ts";
import type { Carrier, Label } from "../src/carrier.ts";
import { CarrierFailure } from "../src/errors.ts";
import { memoryStore } from "../src/memory-store.ts";
import type { Order } from "../src/order.ts";
// Zero-delay backoff: retries run immediately, so no test waits on real time.
const noDelay = Schedule.forever;
const seed: ReadonlyArray<Order> = [{ id: "o1", customerId: "c1", status: "open", lines: [] }];
// Each entry is one carrier response, consumed in order.
function scriptedCarrier(responses: ReadonlyArray<Label | CarrierFailure>) {
  const keys: string[] = [];
  let calls = 0;
  const carrier: Carrier = {
    createLabel: (input) =>
      Effect.suspend(() => {
        keys.push(input.idempotencyKey);
        const response = responses[calls++];
        if (response instanceof CarrierFailure) return Effect.fail(response);
        return Effect.succeed(response ?? { tracking: "unexpected" });
      }),
  };
  return { carrier, keys, calls: () => calls };
}
test("shipping returns tracking and persists shipped state", async () => {
  const store = memoryStore([{ id: "o1", customerId: "c1", status: "open", lines: [] }]);
  const service = api(store, { createLabel: () => Effect.succeed({ tracking: "t1" }) });
  assert.deepEqual(await Effect.runPromise(service.ship("o1")), { tracking: "t1" });
  assert.equal((await Effect.runPromise(store.get("o1")))?.status, "shipped");
});
test("shipping succeeds after transient carrier failures with one idempotency key", async () => {
  const store = memoryStore(seed);
  const { carrier, keys, calls } = scriptedCarrier([
    new CarrierFailure(true),
    new CarrierFailure(true),
    { tracking: "t2" },
  ]);
  const service = api(store, carrier, noDelay);
  assert.deepEqual(await Effect.runPromise(service.ship("o1")), { tracking: "t2" });
  assert.equal(calls(), 3);
  assert.deepEqual(keys, ["ship:o1", "ship:o1", "ship:o1"]);
  assert.equal((await Effect.runPromise(store.get("o1")))?.status, "shipped");
});
test("shipping gives up after three transient attempts and leaves state unchanged", async () => {
  const store = memoryStore(seed);
  const { carrier, keys, calls } = scriptedCarrier([
    new CarrierFailure(true),
    new CarrierFailure(true),
    new CarrierFailure(true),
    { tracking: "unreachable" },
  ]);
  const service = api(store, carrier, noDelay);
  const failure = await Effect.runPromise(service.ship("o1").pipe(Effect.flip));
  assert.ok(failure instanceof CarrierFailure);
  assert.equal(failure.retryable, true);
  assert.equal(calls(), 3);
  assert.deepEqual(keys, ["ship:o1", "ship:o1", "ship:o1"]);
  assert.deepEqual(await Effect.runPromise(store.get("o1")), seed[0]);
});
test("shipping does not retry a permanent carrier failure", async () => {
  const store = memoryStore(seed);
  const { carrier, keys, calls } = scriptedCarrier([new CarrierFailure(false), { tracking: "unreachable" }]);
  const service = api(store, carrier, noDelay);
  const failure = await Effect.runPromise(service.ship("o1").pipe(Effect.flip));
  assert.ok(failure instanceof CarrierFailure);
  assert.equal(failure.retryable, false);
  assert.equal(calls(), 1);
  assert.deepEqual(keys, ["ship:o1"]);
  assert.deepEqual(await Effect.runPromise(store.get("o1")), seed[0]);
});
test("shipping does not call the carrier for a missing order", async () => {
  const store = memoryStore(seed);
  const { carrier, calls } = scriptedCarrier([{ tracking: "unreachable" }]);
  const service = api(store, carrier, noDelay);
  await assert.rejects(Effect.runPromise(service.ship("missing")));
  assert.equal(calls(), 0);
});

