import type { Carrier } from "./carrier.ts";
import { CarrierFailure } from "./errors.ts";
import type { OrderStore } from "./order-store.ts";
import { orders } from "./orders.ts";
// Two retries after the first attempt: 3 attempts total. Only retryable carrier failures are retried.
export const carrierRetry = {
  times: 2,
  schedule: Schedule.exponential("250 millis"),
  while: (error: unknown) => error instanceof CarrierFailure && error.retryable,
};
export function shipping(store: OrderStore, carrier: Carrier, retry = carrierRetry) {
  return Effect.fn("shipping.ship")(function* (id: string) {
    const order = yield* orders(store).find(id);
    // Every attempt reuses the same idempotency key, so the carrier can deduplicate retries.
    const label = yield* Effect.retry(
      carrier.createLabel({ orderId: id, idempotencyKey: `ship:${id}` }),
      retry,
    );
    yield* store.put({ ...order, status: "shipped" });
    return label;
  });
}

