import { Effect, Schedule } from "effect";
import type { Carrier } from "./carrier.ts";
import { CarrierFailure } from "./errors.ts";
import type { OrderStore } from "./order-store.ts";
import { orders } from "./orders.ts";
// Total attempts, including the first call. Retries are `MAX_ATTEMPTS - 1`.
const MAX_ATTEMPTS = 3;
export const defaultBackoff: Schedule.Schedule<unknown, CarrierFailure> = Schedule.exponential("200 millis");
const isRetryable = (error: CarrierFailure) => error instanceof CarrierFailure && error.retryable;
export function shipping(
  store: OrderStore,
  carrier: Carrier,
  backoff: Schedule.Schedule<unknown, CarrierFailure> = defaultBackoff,
) {
  return Effect.fn("shipping.ship")(function* (id: string) {
    const order = yield* orders(store).find(id);
    // One key per order, reused by every attempt so the carrier can deduplicate retries.
    const idempotencyKey = `ship:${id}`;
    const label = yield* carrier
      .createLabel({ orderId: id, idempotencyKey })
      .pipe(Effect.retry({ schedule: backoff, times: MAX_ATTEMPTS - 1, while: isRetryable }));
    yield* store.put({ ...order, status: "shipped" });
    return label;
  });
}

