import test from "node:test";
import assert from "node:assert/strict";
import { Clock, Duration, Effect } from "effect";
import type { Carrier, Label } from "../src/carrier.ts";
import { CarrierFailure } from "../src/errors.ts";
import { api } from "../src/api.ts";
import { memoryStore } from "../src/memory-store.ts";
const transient = () => new CarrierFailure(true);
const permanent = () => new CarrierFailure(false);
function scriptedCarrier(outcomes: Array<Effect.Effect<Label, CarrierFailure>>) {
  const keys: string[] = [];
  let calls = 0;
  const carrier: Carrier = {
    createLabel: (input) =>
      Effect.suspend(() => {
        keys.push(input.idempotencyKey);
        const outcome = outcomes[Math.min(calls, outcomes.length - 1)];
        calls += 1;
        return outcome;
      }),
  };
  return { carrier, keys, calls: () => calls };
}
// Replaces real sleeping with a recorded no-op so retry delays cost no wall time.
function runWithoutSleeping<A, E>(effect: Effect.Effect<A, E>, sleeps: Duration.Duration[]) {
  return Effect.runPromise(
    Effect.gen(function* () {
      const clock = yield* Clock.Clock;
      return yield* effect.pipe(
        Effect.provideService(
          Clock.Clock,
          Object.assign(Object.create(clock), {
            sleep: (duration: Duration.Duration) => Effect.sync(() => void sleeps.push(duration)),
          }),
        ),
      );
    }),
  );
}
const openOrder = { id: "o1", customerId: "c1", status: "open", lines: [] } as const;
test("shipping retries transient failures with the same idempotency key and then persists shipped", async () => {
  const store = memoryStore([openOrder]);
  const scripted = scriptedCarrier([
    Effect.fail(transient()),
    Effect.fail(transient()),
    Effect.succeed({ tracking: "t1" }),
  ]);
  const sleeps: Duration.Duration[] = [];
  const service = api(store, scripted.carrier);
  assert.deepEqual(await runWithoutSleeping(service.ship("o1"), sleeps), { tracking: "t1" });
  assert.equal(scripted.calls(), 3);
  assert.deepEqual(scripted.keys, ["ship:o1", "ship:o1", "ship:o1"]);
  assert.equal(sleeps.length, 2);
  assert.equal((await Effect.runPromise(store.get("o1")))?.status, "shipped");
});
test("shipping gives up after three transient attempts and leaves the order open", async () => {
  const store = memoryStore([openOrder]);
  const scripted = scriptedCarrier([Effect.fail(transient())]);
  const sleeps: Duration.Duration[] = [];
  const service = api(store, scripted.carrier);
  const error = await runWithoutSleeping(Effect.flip(service.ship("o1")), sleeps);
  assert.ok(error instanceof CarrierFailure);
  assert.equal(error.retryable, true);
  assert.equal(scripted.calls(), 3);
  assert.deepEqual(scripted.keys, ["ship:o1", "ship:o1", "ship:o1"]);
  assert.equal(sleeps.length, 2);
  assert.equal((await Effect.runPromise(store.get("o1")))?.status, "open");
});
test("shipping does not retry a permanent carrier failure and leaves the order open", async () => {
  const store = memoryStore([openOrder]);
  const scripted = scriptedCarrier([Effect.fail(permanent())]);
  const sleeps: Duration.Duration[] = [];
  const service = api(store, scripted.carrier);
  const error = await runWithoutSleeping(Effect.flip(service.ship("o1")), sleeps);
  assert.ok(error instanceof CarrierFailure);
  assert.equal(error.retryable, false);
  assert.equal(scripted.calls(), 1);
  assert.equal(sleeps.length, 0);
  assert.equal((await Effect.runPromise(store.get("o1")))?.status, "open");
});

