import test from "node:test";
import assert from "node:assert/strict";
import { Effect, Fiber } from "effect";
import { TestClock } from "effect/testing";
import { api } from "../src/api.ts";
import { CarrierFailure } from "../src/errors.ts";
import { memoryStore } from "../src/memory-store.ts";
test("shipping returns tracking and persists shipped state", async () => {
  const store = memoryStore([{ id: "o1", customerId: "c1", status: "open", lines: [] }]);
  const service = api(store, { createLabel: () => Effect.succeed({ tracking: "t1" }) });
  assert.deepEqual(await Effect.runPromise(service.ship("o1")), { tracking: "t1" });
  assert.equal((await Effect.runPromise(store.get("o1")))?.status, "shipped");
});

const openOrder = { id: "o1", customerId: "c1", status: "open" as const, lines: [] };

test("shipping retries transient failures with the same idempotency key", async () => {
  const store = memoryStore([openOrder]);
  const keys: string[] = [];
  let attempts = 0;
  const service = api(store, {
    createLabel: ({ idempotencyKey }) => {
      keys.push(idempotencyKey);
      attempts++;
      return attempts < 3
        ? Effect.fail(new CarrierFailure(true))
        : Effect.succeed({ tracking: "t2" });
    }
  });

  const program = Effect.gen(function*() {
    const fiber = yield* service.ship("o1").pipe(Effect.forkChild);
    yield* TestClock.adjust("2 millis");
    return yield* Fiber.join(fiber);
  });
  const result = await Effect.runPromise(Effect.provide(program, TestClock.layer()));
  assert.deepEqual(result, { tracking: "t2" });
  assert.equal(attempts, 3);
  assert.deepEqual(keys, ["ship:o1", "ship:o1", "ship:o1"]);
  assert.equal((await Effect.runPromise(store.get("o1")))?.status, "shipped");
});

test("shipping stops after three transient failures and leaves the order open", async () => {
  const store = memoryStore([openOrder]);
  const keys: string[] = [];
  const service = api(store, {
    createLabel: ({ idempotencyKey }) => {
      keys.push(idempotencyKey);
      return Effect.fail(new CarrierFailure(true));
    }
  });

  const program = Effect.gen(function*() {
    const fiber = yield* service.ship("o1").pipe(Effect.forkChild);
    yield* TestClock.adjust("2 millis");
    return yield* Fiber.join(fiber);
  });
  await assert.rejects(Effect.runPromise(Effect.provide(program, TestClock.layer())), CarrierFailure);
  assert.equal(keys.length, 3);
  assert.deepEqual(keys, ["ship:o1", "ship:o1", "ship:o1"]);
  assert.deepEqual(await Effect.runPromise(store.get("o1")), openOrder);
});

test("shipping does not retry permanent failures and leaves the order open", async () => {
  const store = memoryStore([openOrder]);
  let attempts = 0;
  const service = api(store, {
    createLabel: () => {
      attempts++;
      return Effect.fail(new CarrierFailure(false));
    }
  });

  await assert.rejects(Effect.runPromise(service.ship("o1")), CarrierFailure);
  assert.equal(attempts, 1);
  assert.deepEqual(await Effect.runPromise(store.get("o1")), openOrder);
});

