import assert from "node:assert/strict";
import { Effect } from "effect";
import { api } from "../src/api.ts";
import { CarrierFailure } from "../src/errors.ts";
import { memoryStore } from "../src/memory-store.ts";

const openOrder = { id: "o1", customerId: "c1", status: "open" as const, lines: [] };

test("shipping succeeds after transient failures with a stable idempotency key", async () => {
  const store = memoryStore([openOrder]);
  const calls: Array<{ orderId: string; idempotencyKey: string }> = [];
  const service = api(store, {
    createLabel: (input) => {
      calls.push(input);
      return calls.length < 3
        ? Effect.fail(new CarrierFailure(true))
        : Effect.succeed({ tracking: "t1" });
    },
  });

  assert.deepEqual(await Effect.runPromise(service.ship("o1")), { tracking: "t1" });
  assert.equal(calls.length, 3);
  assert.deepEqual(calls, Array.from({ length: 3 }, () => ({ orderId: "o1", idempotencyKey: "ship:o1" })));
  assert.equal((await Effect.runPromise(store.get("o1")))?.status, "shipped");
});

test("shipping stops after three transient failures and leaves the order unchanged", async () => {
  const store = memoryStore([openOrder]);
  let calls = 0;
  const service = api(store, {
    createLabel: () => {
      calls++;
      return Effect.fail(new CarrierFailure(true));
    },
  });

  const failure = await Effect.runPromise(Effect.flip(service.ship("o1")));
  assert.ok(failure instanceof CarrierFailure);
  assert.equal(calls, 3);
  assert.equal((await Effect.runPromise(store.get("o1")))?.status, "open");
});

test("shipping does not retry permanent failures and leaves the order unchanged", async () => {
  const store = memoryStore([openOrder]);
  let calls = 0;
  const service = api(store, {
    createLabel: () => {
      calls++;
      return Effect.fail(new CarrierFailure(false));
    },
  });

  const failure = await Effect.runPromise(Effect.flip(service.ship("o1")));
  assert.ok(failure instanceof CarrierFailure);
  assert.equal(calls, 1);
  assert.equal((await Effect.runPromise(store.get("o1")))?.status, "open");
});

