import test from "node:test";
import assert from "node:assert/strict";
import { Effect } from "effect";
import { api } from "../src/api.ts";
import { memoryStore } from "../src/memory-store.ts";
import { CarrierFailure } from "../src/errors.ts";
test("shipping returns tracking and persists shipped state", async () => {
  const store = memoryStore([{ id: "o1", customerId: "c1", status: "open", lines: [] }]);
  const service = api(store, { createLabel: () => Effect.succeed({ tracking: "t1" }) });
  assert.deepEqual(await Effect.runPromise(service.ship("o1")), { tracking: "t1" });
  assert.equal((await Effect.runPromise(store.get("o1")))?.status, "shipped");
});

test("shipping retries transient failures with one idempotency key", async () => {
  const store = memoryStore([{ id: "o1", customerId: "c1", status: "open", lines: [] }]);
  const keys: string[] = [];
  let attempts = 0;
  const service = api(store, { createLabel: ({ idempotencyKey }) => {
    keys.push(idempotencyKey);
    attempts++;
    return attempts < 3 ? Effect.fail(new CarrierFailure(true)) : Effect.succeed({ tracking: "t1" });
  } });
  assert.deepEqual(await Effect.runPromise(service.ship("o1")), { tracking: "t1" });
  assert.equal(attempts, 3);
  assert.deepEqual(keys, ["ship:o1", "ship:o1", "ship:o1"]);
  assert.equal((await Effect.runPromise(store.get("o1")))?.status, "shipped");
});

test("shipping stops after three transient failures without changing state", async () => {
  const store = memoryStore([{ id: "o1", customerId: "c1", status: "open", lines: [] }]);
  let attempts = 0;
  const service = api(store, { createLabel: () => { attempts++; return Effect.fail(new CarrierFailure(true)); } });
  await assert.rejects(Effect.runPromise(service.ship("o1")), CarrierFailure);
  assert.equal(attempts, 3);
  assert.equal((await Effect.runPromise(store.get("o1")))?.status, "open");
});

test("shipping does not retry permanent failures or change state", async () => {
  const store = memoryStore([{ id: "o1", customerId: "c1", status: "open", lines: [] }]);
  let attempts = 0;
  const service = api(store, { createLabel: () => { attempts++; return Effect.fail(new CarrierFailure(false)); } });
  await assert.rejects(Effect.runPromise(service.ship("o1")), CarrierFailure);
  assert.equal(attempts, 1);
  assert.equal((await Effect.runPromise(store.get("o1")))?.status, "open");
});

