import { Effect, Schedule } from "effect";
import type { Carrier } from "./carrier.ts";
import type { OrderStore } from "./order-store.ts";
import type { CarrierFailure } from "./errors.ts";
import { orders } from "./orders.ts";
export type CarrierRetry = Schedule.Schedule<unknown, CarrierFailure>;
// Exponential backoff with at most two retries: three attempts in total.
export const carrierRetry: CarrierRetry = Schedule.exponential("200 millis").pipe(
  Schedule.upTo({ times: 2 }),
);
export function shipping(store: OrderStore, carrier: Carrier, retry: CarrierRetry = carrierRetry) {
  return Effect.fn("shipping.ship")(function* (id: string) {
    const order = yield* orders(store).find(id);
    const idempotencyKey = `ship:${id}`;
    const label = yield* Effect.suspend(() =>
      carrier.createLabel({ orderId: id, idempotencyKey }),
    ).pipe(Effect.retry({ schedule: retry, while: (failure) => failure.retryable }));
    yield* store.put({ ...order, status: "shipped" });
    return label;
  });
}

