final.tests/shipping.test.ts:
import test from "node:test";
import assert from "node:assert/strict";
import { Effect, Schedule } from "effect";
import { api } from "../src/api.ts";
import type { Carrier, Label } from "../src/carrier.ts";
import { CarrierFailure } from "../src/errors.ts";
import { memoryStore } from "../src/memory-store.ts";
import { shipping } from "../src/shipping.ts";

// Zero-delay policy: retries happen without any real-time sleep.
const noDelayRetry = Schedule.recurs(2);

type Outcome = "ok" | "transient" | "permanent";

function scriptedCarrier(outcomes: ReadonlyArray<Outcome>) {
  const keys: string[] = [];
  let attempt = 0;
  const carrier: Carrier = {
    createLabel: (input) =>
      Effect.suspend(() => {
        keys.push(input.idempotencyKey);
        const outcome = outcomes[Math.min(attempt, outcomes.length - 1)];
        attempt += 1;
        if (outcome === "ok") return Effect.succeed<Label>({ tracking: "t1" });
        return Effect.fail(new CarrierFailure(outcome === "transient"));
      }),
  };
  return { carrier, keys, attempts: () => attempt };
}

const openOrder = () => memoryStore([{ id: "o1", customerId: "c1", status: "open", lines: [] }]);

test("shipping returns tracking and persists shipped state", async () => {
  const store = openOrder();
  const service = api(store, { createLabel: () => Effect.succeed({ tracking: "t1" }) });
  assert.deepEqual(await Effect.runPromise(service.ship("o1")), { tracking: "t1" });
  assert.equal((await Effect.runPromise(store.get("o1")))?.status, "shipped");
});

test("shipping succeeds after transient carrier failures with one idempotency key", async () => {
  const store = openOrder();
  const { carrier, keys, attempts } = scriptedCarrier(["transient", "transient", "ok"]);
  const label = await Effect.runPromise(shipping(store, carrier, noDelayRetry)("o1"));
  assert.deepEqual(label, { tracking: "t1" });
  assert.equal(attempts(), 3);
  assert.deepEqual(keys, ["ship:o1", "ship:o1", "ship:o1"]);
  assert.equal((await Effect.runPromise(store.get("o1")))?.status, "shipped");
});

test("shipping stops after three attempts when transient failures are exhausted", async () => {
  const store = openOrder();
  const { carrier, keys, attempts } = scriptedCarrier(["transient"]);
  const error = await Effect.runPromise(
    Effect.flip(shipping(store, carrier, noDelayRetry)("o1")),
  );
  assert.ok(error instanceof CarrierFailure);
  assert.equal(error.retryable, true);
  assert.equal(attempts(), 3);
  assert.deepEqual(keys, ["ship:o1", "ship:o1", "ship:o1"]);
  assert.equal((await Effect.runPromise(store.get("o1")))?.status, "open");
});

test("shipping never retries a permanent carrier failure", async () => {
  const store = openOrder();
  const { carrier, keys, attempts } = scriptedCarrier(["permanent", "ok"]);
  const error = await Effect.runPromise(
    Effect.flip(shipping(store, carrier, noDelayRetry)("o1")),
  );
  assert.ok(error instanceof CarrierFailure);
  assert.equal(error.retryable, false);
  assert.equal(attempts(), 1);
  assert.deepEqual(keys, ["ship:o1"]);
  assert.equal((await Effect.runPromise(store.get("o1")))?.status, "open");
});

test("failed shipping leaves the stored order unchanged", async () => {
  const store = openOrder();
  const before = await Effect.runPromise(store.get("o1"));
  const { carrier } = scriptedCarrier(["permanent"]);
  await Effect.runPromise(Effect.flip(shipping(store, carrier, noDelayRetry)("o1")));
  assert.deepEqual(await Effect.runPromise(store.get("o1")), before);
});

