import test from "node:test";
import assert from "node:assert/strict";
import { Effect } from "effect";
import { api } from "../src/api.ts";
import { memoryStore } from "../src/memory-store.ts";
import { OrderNotFound } from "../src/errors.ts";
import type { Order } from "../src/order.ts";

const order: Order = {
  id: "discount-order",
  customerId: "customer",
  status: "open",
  lines: [{ sku: "item", unitCents: 2000, quantity: 1 }],
};

const discount = (percent: number) =>
  Effect.runPromise(api(memoryStore([order]), { ship: () => Effect.void }).discounted(order.id, percent));

test("discounted leaves the full subtotal at 0 percent", async () => {
  assert.equal(await discount(0), 2000);
});

test("discounted leaves zero at 100 percent", async () => {
  assert.equal(await discount(100), 0);
});

test("discounted rounds a fractional-cent result once to the nearest cent", async () => {
  const fractionalOrder = { ...order, lines: [{ sku: "item", unitCents: 5, quantity: 1 }] };
  const result = await Effect.runPromise(
    api(memoryStore([fractionalOrder]), { ship: () => Effect.void }).discounted(fractionalOrder.id, 10),
  );
  assert.equal(result, 5);
});

test("discounted leaves 1600 cents after a 20 percent discount on 2000 cents", async () => {
  assert.equal(await discount(20), 1600);
});

test("discounted preserves the missing-order error contract", async () => {
  const result = await Effect.runPromise(
    Effect.flip(api(memoryStore(), { ship: () => Effect.void }).discounted("missing", 20)),
  );
  assert.equal(result._tag, "OrderNotFound");
  assert.equal(result.orderId, "missing");
});

