import { Effect } from "effect";
import { api } from "../src/api.ts";
import { remaining } from "../src/pricing.ts";
import { memoryStore } from "../src/memory-store.ts";
const order = {
  id: "o1",
  customerId: "c1",
  status: "open" as const,
  lines: [{ sku: "a", unitCents: 1000, quantity: 2 }],
};
const carrier = { createLabel: () => Effect.die("unused") };
test("0% leaves the subtotal unchanged", () => {
  assert.equal(remaining(2000, 0), 2000);
});
test("100% leaves nothing", () => {
  assert.equal(remaining(2000, 100), 0);
});
test("a fractional-cent result rounds once to the nearest cent", () => {
  // 999 * 0.85 = 849.15
  assert.equal(remaining(999, 15), 849);
});
test("20% off a 2000-cent subtotal leaves 1600 cents", () => {
  assert.equal(remaining(2000, 20), 1600);
});
test("discounted applies the percentage to the order subtotal", async () => {
  const result = await Effect.runPromise(
    api(memoryStore([order]), carrier).discounted("o1", 20),
  );
  assert.equal(result, 1600);
});
test("discounted keeps the OrderNotFound failure for unknown orders", async () => {
  const error = await Effect.runPromise(
    Effect.flip(api(memoryStore(), carrier).discounted("absent", 20)),
  );
  assert.equal(error["_tag"], "OrderNotFound");
  assert.equal(error.orderId, "absent");
});

